43	     * falling in a known 4-digit range wins (NSW 2000-2099, VIC 3000-3099,
44	     * QLD 4000-4099). When the postcode is absent or in no known range, it falls
45	     * back to a fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
46	     * Brisbane-&gt;QLD). Returns {@code UNKNOWN} when neither source resolves.
47	     */
48	    default String locality(Owner owner) {
49	        String region = regionFromPostcode(owner);
50	        if (region != null) {
51	            return region;
52	        }
53	        return cityRegion(owner);
54	    }
