58	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
59	     * when the city is absent or not in the table.
60	     */
61	    default String cityRegion(Owner owner) {
62	        String city = owner.getCity();
63	        if (city == null) {
64	            return "UNKNOWN";
65	        }
66	        switch (city) {
67	            case "Sydney":
68	                return "NSW";
69	            case "Melbourne":
70	                return "VIC";
71	            case "Brisbane":
72	                return "QLD";
73	            default:
74	                return "UNKNOWN";
75	        }
76	    }
